import React, { useEffect, useState } from "react";
import './CarFilter.css';

export default function CarFilter() {

    const [brandFilter, setBrandFilter] = useState(null)
    const [modelFilter, setModelFilter] = useState(null)
    const [typeFilter, setTypeFilter] = useState(null)
    const [allCars, setAllCars] = useState([]);

    const [cars, setCars] = useState([])

    useEffect(() => {
        const fetchFilteredCars = async () => {

            const params  =  new URLSearchParams();

            let url = "http://localhost:5000/cars?";

            if (brandFilter) {
                params.append("brand", brandFilter)
            }

            if (modelFilter) {
                params.append("model", modelFilter)
            }

            if (typeFilter) {
                params.append("type", modelFilter)
            }

            const response = await fetch(
                `http://localhost:5000/cars?${params.toString()}`
            );

            const data = await response.json();

            setCars(data);
        }

        fetchFilteredCars();
    },[brandFilter, modelFilter, typeFilter])

    useEffect(() => {
        const fetchAllCars = async ( ) => {
            let url = "http://localhost:5000/cars";

            const response = await fetch(url);

            const data = await response.json()

            setAllCars(data);
            setCars(data);
        }
        fetchAllCars();
    },[])

    const brands = [...new Set(allCars.map((car) => car.brand))];

    const models = [...new Set(allCars.map((car) => car.model))];

    const types = [...new Set(cars.map((car) => car.type))];

    useEffect(() => {
        console.log(types)
    },[models])

    useEffect(() => {
        console.log(brandFilter)
    },[brandFilter])

    return (
        <div className="root">
            <div className="filter">
                <div className="brand">
                    <h3>--- Marque ---</h3>
                    {brands.length != 0 && brands.map((brand, index) => (
                        <div className="input" key={brand}>
                            <input type="checkbox" checked={brandFilter === brand} onChange={() => setBrandFilter(brandFilter === brand ? null : brand)}/>
                            <label>{brand}</label>
                        </div>
                    ))}
                </div>
                <div>
                    <h3>--- Modèle ---</h3>  
                    {models.length != 0 && models.map((model, index) => (
                        <div className="input" key={model}>
                            <input type="checkbox" checked={modelFilter === model} onChange={() => setModelFilter(modelFilter === model ? null : model)}  />
                            <label>{model}</label>
                        </div>
                    ))}
                </div>
                <div>
                    <h3>--- Type ---</h3>
                    {types.length != 0 && types.map((type, index) => (
                        <div className="input" key={type}>
                            <input type="checkbox" checked={typeFilter === type} onChange={() => setTypeFilter(typeFilter === type ? null : type)}  />
                            <label>{type}</label>
                        </div>
                    ))}
                </div>
            </div>

            <div className="tab">
                <div className="titles">
                    <div className="titleCol"> marque </div>
                    <div className="titleCol"> modèle </div>
                    <div className="titleCol"> type</div>
                </div>
                <div className="car">
                    {cars.length > 0 ? cars.map((car, index) => (
                        <div key={car.id} className={`${"elements"} ${index % 2 === 0 ? "grayBackground" : ''}`} >
                            <div className="col">{car.brand}</div>
                            <div className="col">{car.model}</div>
                            <div className="col">{car.type} </div>
                        </div>
                    )) : 
                        <div className="notFound">
                            aucun véhicule ne correspond à votre recherche
                        </div>
                    }
                </div>
            </div>
        </div>
    )
};
